approvals.command:
cat >> src/math.js <<'EOF'

export function clamp(value, min, max) {
  if (min > max) {
    throw new RangeError('min must not be greater than max')
  }
  if (value < min) return min
  if (value > max) return max
  return value
}
EOF
sed -i "s/import { add }/import { add, clamp }/" test/math.test.js
cat >> test/math.test.js <<'EOF'

test('clamp returns value inside the range unchanged', () => assert.equal(clamp(5, 0, 10), 5))
test('clamp returns min when value is below min', () => assert.equal(clamp(-3, 0, 10), 0))
test('clamp returns max when value is above max', () => assert.equal(clamp(42, 0, 10), 10))
test('clamp bounds are inclusive', () => {
  assert.equal(clamp(0, 0, 10), 0)
  assert.equal(clamp(10, 0, 10), 10)
})
test('clamp works when min equals max', () => assert.equal(clamp(7, 3, 3), 3))
test('clamp throws RangeError when min > max', () => {
  assert.throws(() => clamp(1, 5, 2), RangeError)
})
EOF
npm test 2>&1 | tail -15; git add src/math.js test/math.test.js; git commit -q -m "Add clamp to math

